"""Write RULES.md from the rule registry."""

from __future__ import annotations

import dataclasses

from thesis_lint.registry import all_rules, attribute


def render() -> str:
    """Return the Markdown text of RULES.md."""
    lines = [
        "# Rules",
        "",
        "This file is generated by `thesis-lint rules-doc`. Do not edit it.",
        "",
        "Suppress a finding with a comment on its line or on the line before it:",
        "`// ignore: rule.id,other.id; reason` (in `.bib` files: `% ignore: ...`).",
        "The engine reports `ignore.syntax` (error), `ignore.unknown-rule` (error)",
        "and `ignore.unused` (warning) for problems of these comments.",
        "",
    ]
    rules = all_rules()
    for pack in sorted({rule.pack for rule in rules.values()}):
        lines.extend([f"## Pack `{pack}`", ""])
        for rule in (r for r in rules.values() if r.pack == pack):
            lines.extend([f"### `{rule.id}`", "", rule.summary, ""])
            lines.append(f"- Default severity: {rule.severity}")
            lines.append(f"- Input: {rule.needs}")
            if rule.submission:
                lines.append("- Submission rule: warning in the draft profile")
            if dataclasses.is_dataclass(rule.params) and not isinstance(rule.params, type):
                for field in dataclasses.fields(rule.params):
                    value = attribute(rule.params, field.name)
                    lines.append(f"- Parameter `{field.name.replace('_', '-')}`: `{value!r}`")
            for source in rule.sources:
                quote = f": „{source.quote}“" if source.quote else ""
                lines.append(f"- Source: {source.source}, {source.page}{quote}")
            lines.append("")
    return "\n".join(lines).rstrip() + "\n"
